    try _v.visit(field: VT.ELEMENTS, fieldName: "ELEMENTS", required: false, type: ForwardOffset<mplElements>.self)
    try _v.visit(field: VT.STATE, fieldName: "STATE", required: false, type: ForwardOffset<ephemerisDataLine>.self)
