///  One impulsive (or short finite) burn of a plan.
public struct mplBurn: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MPL" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: mplBurn.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let NAME: VOffset = 4
    static let PURPOSE: VOffset = 6
    static let EPOCH_MS: VOffset = 8
    static let OFFSET_S: VOffset = 10
    static let TRUE_ANOMALY_DEG: VOffset = 12
    static let AXES: VOffset = 14
    static let DELTA_V: VOffset = 16
    static let MAGNITUDE_KM_S: VOffset = 18
    static let DURATION_S: VOffset = 20
    static let DELTA_MASS_KG: VOffset = 22
    static let REFERENCE_ORBIT: VOffset = 24
    static let ARC_INDEX: VOffset = 26
    static let MANEUVER_ID: VOffset = 28
  }

  ///  Label of the burn within the plan, e.g. "departure", "circularize".
  public var NAME: String? { let o = _accessor.offset(VT.NAME); return o == 0 ? nil : _accessor.string(at: o) }
  public var NAMESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.NAME) }
  ///  What the burn does.
  public var PURPOSE: maneuverCharacterization { let o = _accessor.offset(VT.PURPOSE); return o == 0 ? .unknown : maneuverCharacterization(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unknown }
  ///  Unix milliseconds of the burn (its start for a finite burn); 0 = not
  ///  anchored to an absolute time (use OFFSET_S).
  public var EPOCH_MS: Int64 { let o = _accessor.offset(VT.EPOCH_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  ///  Seconds from the plan's start (PLAN_EPOCH_MS) to the burn.
  public var OFFSET_S: Double { let o = _accessor.offset(VT.OFFSET_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  True anomaly on the orbit being left at which to burn, deg; NaN = not
  ///  stated.
  public var TRUE_ANOMALY_DEG: Double { let o = _accessor.offset(VT.TRUE_ANOMALY_DEG); return o == 0 ? .nan : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Axes DELTA_V is expressed in.
  public var AXES: mplAxes { let o = _accessor.offset(VT.AXES); return o == 0 ? .unspecified : mplAxes(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  ///  Delta-v vector, km/s, 3 values in AXES order. Components are signed (a
  ///  retrograde in-track burn has a negative I component).
  public var DELTA_V: FlatbufferVector<Double> { return _accessor.vector(at: VT.DELTA_V, byteSize: 8) }
  public func withUnsafePointerToDeltaV<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.DELTA_V, body: body) }
  ///  Delta-v magnitude, km/s (always >= 0).
  public var MAGNITUDE_KM_S: Double { let o = _accessor.offset(VT.MAGNITUDE_KM_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Burn duration, s; 0 = impulsive.
  public var DURATION_S: Double { let o = _accessor.offset(VT.DURATION_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Propellant consumed, kg; 0 = not computed.
  public var DELTA_MASS_KG: Double { let o = _accessor.offset(VT.DELTA_MASS_KG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  The orbit the burn's axes are built from (the chaser's for an absolute
  ///  burn, the reference orbit at the burn for a relative-motion leg); empty
  ///  = the plan's initial orbit.
  public var REFERENCE_ORBIT: mplElements? { let o = _accessor.offset(VT.REFERENCE_ORBIT); return o == 0 ? nil : mplElements(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Index into ARCS of the arc this burn starts; -1 = none (the final burn).
  public var ARC_INDEX: Int32 { let o = _accessor.offset(VT.ARC_INDEX); return o == 0 ? -1 : _accessor.readBuffer(of: Int32.self, at: o) }
  ///  Identifier of the $MNV this burn became once committed; empty until
  ///  then.
  public var MANEUVER_ID: String? { let o = _accessor.offset(VT.MANEUVER_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var MANEUVER_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.MANEUVER_ID) }
  public static func startmplBurn(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 13) }
  public static func add(NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NAME, at: VT.NAME) }
  public static func add(PURPOSE: maneuverCharacterization, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PURPOSE.rawValue, def: 9, at: VT.PURPOSE) }
  public static func add(EPOCH_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: EPOCH_MS, def: 0, at: VT.EPOCH_MS) }
  public static func add(OFFSET_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: OFFSET_S, def: 0.0, at: VT.OFFSET_S) }
  public static func add(TRUE_ANOMALY_DEG: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TRUE_ANOMALY_DEG, def: .nan, at: VT.TRUE_ANOMALY_DEG) }
  public static func add(AXES: mplAxes, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AXES.rawValue, def: 0, at: VT.AXES) }
  public static func addVectorOf(DELTA_V: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DELTA_V, at: VT.DELTA_V) }
  public static func add(MAGNITUDE_KM_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAGNITUDE_KM_S, def: 0.0, at: VT.MAGNITUDE_KM_S) }
  public static func add(DURATION_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DURATION_S, def: 0.0, at: VT.DURATION_S) }
  public static func add(DELTA_MASS_KG: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DELTA_MASS_KG, def: 0.0, at: VT.DELTA_MASS_KG) }
  public static func add(REFERENCE_ORBIT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REFERENCE_ORBIT, at: VT.REFERENCE_ORBIT) }
  public static func add(ARC_INDEX: Int32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ARC_INDEX, def: -1, at: VT.ARC_INDEX) }
  public static func add(MANEUVER_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: MANEUVER_ID, at: VT.MANEUVER_ID) }
  public static func endmplBurn(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createmplBurn(
    _ fbb: inout FlatBufferBuilder,
    NAMEOffset NAME: Offset = Offset(),
    PURPOSE: maneuverCharacterization = .unknown,
    EPOCH_MS: Int64 = 0,
    OFFSET_S: Double = 0.0,
    TRUE_ANOMALY_DEG: Double = .nan,
    AXES: mplAxes = .unspecified,
    DELTA_VVectorOffset DELTA_V: Offset = Offset(),
    MAGNITUDE_KM_S: Double = 0.0,
    DURATION_S: Double = 0.0,
    DELTA_MASS_KG: Double = 0.0,
    REFERENCE_ORBITOffset REFERENCE_ORBIT: Offset = Offset(),
    ARC_INDEX: Int32 = -1,
    MANEUVER_IDOffset MANEUVER_ID: Offset = Offset()
  ) -> Offset {
    let __start = mplBurn.startmplBurn(&fbb)
    mplBurn.add(NAME: NAME, &fbb)
    mplBurn.add(PURPOSE: PURPOSE, &fbb)
    mplBurn.add(EPOCH_MS: EPOCH_MS, &fbb)
    mplBurn.add(OFFSET_S: OFFSET_S, &fbb)
    mplBurn.add(TRUE_ANOMALY_DEG: TRUE_ANOMALY_DEG, &fbb)
    mplBurn.add(AXES: AXES, &fbb)
    mplBurn.addVectorOf(DELTA_V: DELTA_V, &fbb)
    mplBurn.add(MAGNITUDE_KM_S: MAGNITUDE_KM_S, &fbb)
    mplBurn.add(DURATION_S: DURATION_S, &fbb)
    mplBurn.add(DELTA_MASS_KG: DELTA_MASS_KG, &fbb)
    mplBurn.add(REFERENCE_ORBIT: REFERENCE_ORBIT, &fbb)
    mplBurn.add(ARC_INDEX: ARC_INDEX, &fbb)
    mplBurn.add(MANEUVER_ID: MANEUVER_ID, &fbb)
    return mplBurn.endmplBurn(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PURPOSE, fieldName: "PURPOSE", required: false, type: maneuverCharacterization.self)
    try _v.visit(field: VT.EPOCH_MS, fieldName: "EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.OFFSET_S, fieldName: "OFFSET_S", required: false, type: Double.self)
    try _v.visit(field: VT.TRUE_ANOMALY_DEG, fieldName: "TRUE_ANOMALY_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.AXES, fieldName: "AXES", required: false, type: mplAxes.self)
    try _v.visit(field: VT.DELTA_V, fieldName: "DELTA_V", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.MAGNITUDE_KM_S, fieldName: "MAGNITUDE_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.DURATION_S, fieldName: "DURATION_S", required: false, type: Double.self)
    try _v.visit(field: VT.DELTA_MASS_KG, fieldName: "DELTA_MASS_KG", required: false, type: Double.self)
    try _v.visit(field: VT.REFERENCE_ORBIT, fieldName: "REFERENCE_ORBIT", required: false, type: ForwardOffset<mplElements>.self)
    try _v.visit(field: VT.ARC_INDEX, fieldName: "ARC_INDEX", required: false, type: Int32.self)
    try _v.visit(field: VT.MANEUVER_ID, fieldName: "MANEUVER_ID", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}

///  States sampled along an arc or a whole plan, column-major and parallel:
///  OFFSETS_S has one entry per sample and STATES has STATE_SIZE entries per
///  sample.
public struct mplTrajectory: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MPL" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: mplTrajectory.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let AXES: VOffset = 4
    static let STATE_SIZE: VOffset = 6
    static let OFFSETS_S: VOffset = 8
    static let STATES: VOffset = 10
  }

  ///  Axes and origin of STATES: Inertial = the plan's REFERENCE_FRAME about
  ///  the central body; RIC or VNC = relative to the reference orbit (the
  ///  target), centred on it.
  public var AXES: mplAxes { let o = _accessor.offset(VT.AXES); return o == 0 ? .unspecified : mplAxes(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  ///  Values per sample in STATES: 3 = position only, 6 = position and
  ///  velocity. 0 is read as 6.
  public var STATE_SIZE: UInt8 { let o = _accessor.offset(VT.STATE_SIZE); return o == 0 ? 6 : _accessor.readBuffer(of: UInt8.self, at: o) }
  ///  Seconds from the plan's start, one per sample, signed (negative for a
  ///  track sampled backwards).
  public var OFFSETS_S: FlatbufferVector<Double> { return _accessor.vector(at: VT.OFFSETS_S, byteSize: 8) }
  public func withUnsafePointerToOffsetsS<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.OFFSETS_S, body: body) }
  ///  Positions (km) and velocities (km/s), STATE_SIZE values per sample.
  public var STATES: FlatbufferVector<Double> { return _accessor.vector(at: VT.STATES, byteSize: 8) }
  public func withUnsafePointerToStates<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.STATES, body: body) }
  public static func startmplTrajectory(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 4) }
  public static func add(AXES: mplAxes, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AXES.rawValue, def: 0, at: VT.AXES) }
  public static func add(STATE_SIZE: UInt8, _ fbb: inout FlatBufferBuilder) { fbb.add(element: STATE_SIZE, def: 6, at: VT.STATE_SIZE) }
  public static func addVectorOf(OFFSETS_S: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OFFSETS_S, at: VT.OFFSETS_S) }
  public static func addVectorOf(STATES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATES, at: VT.STATES) }
  public static func endmplTrajectory(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createmplTrajectory(
    _ fbb: inout FlatBufferBuilder,
    AXES: mplAxes = .unspecified,
    STATE_SIZE: UInt8 = 6,
    OFFSETS_SVectorOffset OFFSETS_S: Offset = Offset(),
    STATESVectorOffset STATES: Offset = Offset()
  ) -> Offset {
    let __start = mplTrajectory.startmplTrajectory(&fbb)
    mplTrajectory.add(AXES: AXES, &fbb)
    mplTrajectory.add(STATE_SIZE: STATE_SIZE, &fbb)
    mplTrajectory.addVectorOf(OFFSETS_S: OFFSETS_S, &fbb)
    mplTrajectory.addVectorOf(STATES: STATES, &fbb)
    return mplTrajectory.endmplTrajectory(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.AXES, fieldName: "AXES", required: false, type: mplAxes.self)
    try _v.visit(field: VT.STATE_SIZE, fieldName: "STATE_SIZE", required: false, type: UInt8.self)
    try _v.visit(field: VT.OFFSETS_S, fieldName: "OFFSETS_S", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STATES, fieldName: "STATES", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    _v.finish()
  }
}

///  Solver evidence for an arc or a plan.
