    ITERATIONS: UInt32 = 0,
    STATUS_TEXTOffset STATUS_TEXT: Offset = Offset(),
    RESIDUAL: Double = 0.0,
    RESIDUAL_TOLERANCE: Double = 0.0
  ) -> Offset {
    let __start = mplSolver.startmplSolver(&fbb)
    mplSolver.add(CONVERGED: CONVERGED, &fbb)
    mplSolver.add(ITERATIONS: ITERATIONS, &fbb)
    mplSolver.add(STATUS_TEXT: STATUS_TEXT, &fbb)
    mplSolver.add(RESIDUAL: RESIDUAL, &fbb)
    mplSolver.add(RESIDUAL_TOLERANCE: RESIDUAL_TOLERANCE, &fbb)
    return mplSolver.endmplSolver(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.CONVERGED, fieldName: "CONVERGED", required: false, type: Bool.self)
    try _v.visit(field: VT.ITERATIONS, fieldName: "ITERATIONS", required: false, type: UInt32.self)
    try _v.visit(field: VT.STATUS_TEXT, fieldName: "STATUS_TEXT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.RESIDUAL, fieldName: "RESIDUAL", required: false, type: Double.self)
    try _v.visit(field: VT.RESIDUAL_TOLERANCE, fieldName: "RESIDUAL_TOLERANCE", required: false, type: Double.self)
    _v.finish()
  }
}

