    mplArc.add(NAME: NAME, &fbb)
    mplArc.add(ROLE: ROLE, &fbb)
    mplArc.add(START_OFFSET_S: START_OFFSET_S, &fbb)
    mplArc.add(DURATION_S: DURATION_S, &fbb)
    mplArc.add(REVOLUTIONS: REVOLUTIONS, &fbb)
    mplArc.add(BRANCH: BRANCH, &fbb)
    mplArc.add(CONIC: CONIC, &fbb)
    mplArc.add(SEMI_MAJOR_AXIS_KM: SEMI_MAJOR_AXIS_KM, &fbb)
    mplArc.add(ECCENTRICITY: ECCENTRICITY, &fbb)
    mplArc.add(PERIAPSIS_RADIUS_KM: PERIAPSIS_RADIUS_KM, &fbb)
    mplArc.add(APOAPSIS_RADIUS_KM: APOAPSIS_RADIUS_KM, &fbb)
    mplArc.add(PERIOD_S: PERIOD_S, &fbb)
    mplArc.add(START_STATE: START_STATE, &fbb)
    mplArc.add(END_STATE: END_STATE, &fbb)
    mplArc.add(STATE_AXES: STATE_AXES, &fbb)
    mplArc.add(DELTA_V_KM_S: DELTA_V_KM_S, &fbb)
    mplArc.add(LAMBERT_Z: LAMBERT_Z, &fbb)
    mplArc.add(SOLVER: SOLVER, &fbb)
    mplArc.add(TRAJECTORY: TRAJECTORY, &fbb)
