    try _v.visit(field: VT.BRANCH, fieldName: "BRANCH", required: false, type: mplLambertBranch.self)
    try _v.visit(field: VT.CONIC, fieldName: "CONIC", required: false, type: mplConic.self)
    try _v.visit(field: VT.SEMI_MAJOR_AXIS_KM, fieldName: "SEMI_MAJOR_AXIS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.ECCENTRICITY, fieldName: "ECCENTRICITY", required: false, type: Double.self)
    try _v.visit(field: VT.PERIAPSIS_RADIUS_KM, fieldName: "PERIAPSIS_RADIUS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.APOAPSIS_RADIUS_KM, fieldName: "APOAPSIS_RADIUS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.PERIOD_S, fieldName: "PERIOD_S", required: false, type: Double.self)
    try _v.visit(field: VT.START_STATE, fieldName: "START_STATE", required: false, type: ForwardOffset<ephemerisDataLine>.self)
    try _v.visit(field: VT.END_STATE, fieldName: "END_STATE", required: false, type: ForwardOffset<ephemerisDataLine>.self)
    try _v.visit(field: VT.STATE_AXES, fieldName: "STATE_AXES", required: false, type: mplAxes.self)
    try _v.visit(field: VT.DELTA_V_KM_S, fieldName: "DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.LAMBERT_Z, fieldName: "LAMBERT_Z", required: false, type: Double.self)
    try _v.visit(field: VT.SOLVER, fieldName: "SOLVER", required: false, type: ForwardOffset<mplSolver>.self)
    try _v.visit(field: VT.TRAJECTORY, fieldName: "TRAJECTORY", required: false, type: ForwardOffset<mplTrajectory>.self)
    _v.finish()
  }
}

