    CLAMPED_TO_FLOOR: Bool = false,
    WITHIN_BUDGET: Bool = false
  ) -> Offset {
    let __start = mplOption.startmplOption(&fbb)
    mplOption.add(NAME: NAME, &fbb)
    mplOption.add(SELECTED: SELECTED, &fbb)
    mplOption.add(REVOLUTIONS: REVOLUTIONS, &fbb)
    mplOption.add(BRANCH: BRANCH, &fbb)
    mplOption.add(DIRECTION: DIRECTION, &fbb)
    mplOption.add(PHASE_ANGLE_DEG: PHASE_ANGLE_DEG, &fbb)
    mplOption.addVectorOf(BURN_DELTA_V_KM_S: BURN_DELTA_V_KM_S, &fbb)
    mplOption.add(TOTAL_DELTA_V_KM_S: TOTAL_DELTA_V_KM_S, &fbb)
    mplOption.add(TOTAL_TIME_S: TOTAL_TIME_S, &fbb)
    mplOption.add(SEMI_MAJOR_AXIS_KM: SEMI_MAJOR_AXIS_KM, &fbb)
    mplOption.add(CLAMPED_TO_FLOOR: CLAMPED_TO_FLOOR, &fbb)
    mplOption.add(WITHIN_BUDGET: WITHIN_BUDGET, &fbb)
    return mplOption.endmplOption(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SELECTED, fieldName: "SELECTED", required: false, type: Bool.self)
    try _v.visit(field: VT.REVOLUTIONS, fieldName: "REVOLUTIONS", required: false, type: UInt32.self)
    try _v.visit(field: VT.BRANCH, fieldName: "BRANCH", required: false, type: mplLambertBranch.self)
    try _v.visit(field: VT.DIRECTION, fieldName: "DIRECTION", required: false, type: mplPhasingDirection.self)
    try _v.visit(field: VT.PHASE_ANGLE_DEG, fieldName: "PHASE_ANGLE_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.BURN_DELTA_V_KM_S, fieldName: "BURN_DELTA_V_KM_S", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.TOTAL_DELTA_V_KM_S, fieldName: "TOTAL_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.TOTAL_TIME_S, fieldName: "TOTAL_TIME_S", required: false, type: Double.self)
    try _v.visit(field: VT.SEMI_MAJOR_AXIS_KM, fieldName: "SEMI_MAJOR_AXIS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.CLAMPED_TO_FLOOR, fieldName: "CLAMPED_TO_FLOOR", required: false, type: Bool.self)
    try _v.visit(field: VT.WITHIN_BUDGET, fieldName: "WITHIN_BUDGET", required: false, type: Bool.self)
    _v.finish()
  }
}

