///  Lambert problem (Lambert, LambertMinimumDeltaV). DEPARTURE and ARRIVAL
///  give the two positions; their velocities, when given, are the velocities
///  of the orbits being left and joined, and make the result's burns real
///  delta-v (LambertMinimumDeltaV requires them, since ranking needs a cost).
public struct mplLambertRequest: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MPL" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: mplLambertRequest.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let DEPARTURE: VOffset = 4
    static let ARRIVAL: VOffset = 6
    static let ENDPOINT_VELOCITIES: VOffset = 8
    static let TIME_OF_FLIGHT_S: VOffset = 10
    static let PROGRADE: VOffset = 12
    static let REVOLUTIONS: VOffset = 14
    static let BRANCH: VOffset = 16
  }

  ///  Departure position (and the departing orbit's velocity), inertial.
  public var DEPARTURE: ephemerisDataLine? { let o = _accessor.offset(VT.DEPARTURE); return o == 0 ? nil : ephemerisDataLine(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Arrival position (and the arrival orbit's velocity), inertial.
  public var ARRIVAL: ephemerisDataLine? { let o = _accessor.offset(VT.ARRIVAL); return o == 0 ? nil : ephemerisDataLine(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  True when DEPARTURE and ARRIVAL carry orbit velocities; false = position
  ///  only (the result then gives the transfer velocities, not delta-v).
  public var ENDPOINT_VELOCITIES: Bool { let o = _accessor.offset(VT.ENDPOINT_VELOCITIES); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Time of flight, s.
  public var TIME_OF_FLIGHT_S: Double { let o = _accessor.offset(VT.TIME_OF_FLIGHT_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  True for a prograde (short-way in the direction of motion) transfer.
  public var PROGRADE: Bool { let o = _accessor.offset(VT.PROGRADE); return o == 0 ? true : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Revolution count of a Lambert problem; the largest count ranked by
  ///  LambertMinimumDeltaV.
  public var REVOLUTIONS: UInt32 { let o = _accessor.offset(VT.REVOLUTIONS); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Lambert: the arc to return when REVOLUTIONS >= 1 (Unspecified = Low).
  ///  LambertMinimumDeltaV: narrows the ranking to one branch (Unspecified =
  ///  rank both).
  public var BRANCH: mplLambertBranch { let o = _accessor.offset(VT.BRANCH); return o == 0 ? .unspecified : mplLambertBranch(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  public static func startmplLambertRequest(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 7) }
  public static func add(DEPARTURE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DEPARTURE, at: VT.DEPARTURE) }
  public static func add(ARRIVAL: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ARRIVAL, at: VT.ARRIVAL) }
  public static func add(ENDPOINT_VELOCITIES: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ENDPOINT_VELOCITIES, def: false,
   at: VT.ENDPOINT_VELOCITIES) }
  public static func add(TIME_OF_FLIGHT_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TIME_OF_FLIGHT_S, def: 0.0, at: VT.TIME_OF_FLIGHT_S) }
  public static func add(PROGRADE: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PROGRADE, def: true,
   at: VT.PROGRADE) }
  public static func add(REVOLUTIONS: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: REVOLUTIONS, def: 0, at: VT.REVOLUTIONS) }
  public static func add(BRANCH: mplLambertBranch, _ fbb: inout FlatBufferBuilder) { fbb.add(element: BRANCH.rawValue, def: 0, at: VT.BRANCH) }
  public static func endmplLambertRequest(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createmplLambertRequest(
    _ fbb: inout FlatBufferBuilder,
    DEPARTUREOffset DEPARTURE: Offset = Offset(),
    ARRIVALOffset ARRIVAL: Offset = Offset(),
    ENDPOINT_VELOCITIES: Bool = false,
    TIME_OF_FLIGHT_S: Double = 0.0,
    PROGRADE: Bool = true,
    REVOLUTIONS: UInt32 = 0,
    BRANCH: mplLambertBranch = .unspecified
  ) -> Offset {
    let __start = mplLambertRequest.startmplLambertRequest(&fbb)
    mplLambertRequest.add(DEPARTURE: DEPARTURE, &fbb)
    mplLambertRequest.add(ARRIVAL: ARRIVAL, &fbb)
    mplLambertRequest.add(ENDPOINT_VELOCITIES: ENDPOINT_VELOCITIES, &fbb)
    mplLambertRequest.add(TIME_OF_FLIGHT_S: TIME_OF_FLIGHT_S, &fbb)
    mplLambertRequest.add(PROGRADE: PROGRADE, &fbb)
    mplLambertRequest.add(REVOLUTIONS: REVOLUTIONS, &fbb)
    mplLambertRequest.add(BRANCH: BRANCH, &fbb)
    return mplLambertRequest.endmplLambertRequest(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DEPARTURE, fieldName: "DEPARTURE", required: false, type: ForwardOffset<ephemerisDataLine>.self)
    try _v.visit(field: VT.ARRIVAL, fieldName: "ARRIVAL", required: false, type: ForwardOffset<ephemerisDataLine>.self)
    try _v.visit(field: VT.ENDPOINT_VELOCITIES, fieldName: "ENDPOINT_VELOCITIES", required: false, type: Bool.self)
    try _v.visit(field: VT.TIME_OF_FLIGHT_S, fieldName: "TIME_OF_FLIGHT_S", required: false, type: Double.self)
    try _v.visit(field: VT.PROGRADE, fieldName: "PROGRADE", required: false, type: Bool.self)
    try _v.visit(field: VT.REVOLUTIONS, fieldName: "REVOLUTIONS", required: false, type: UInt32.self)
    try _v.visit(field: VT.BRANCH, fieldName: "BRANCH", required: false, type: mplLambertBranch.self)
    _v.finish()
  }
}

