  public static func endmplPhasingRequest(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createmplPhasingRequest(
    _ fbb: inout FlatBufferBuilder,
    ORBIT_RADIUS_KM: Double = 0.0,
    PHASE_ANGLE_DEG: Double = 0.0,
    REVOLUTIONS: UInt32 = 0,
    HAS_REVOLUTIONS: Bool = false,
    MAX_REVOLUTIONS: UInt32 = 0,
    CHASEROffset CHASER: Offset = Offset(),
    TARGETOffset TARGET: Offset = Offset(),
    DIRECTION: mplPhasingDirection = .shortest,
    DELTA_V_BUDGET_KM_S: Double = 0.0,
    DELTA_V_BUDGET_FRACTION: Double = 0.0,
    COPLANAR_TOLERANCE_DEG: Double = 0.0,
    HAS_COPLANAR_TOLERANCE: Bool = false,
    ECCENTRICITY_TOLERANCE: Double = 0.0,
    HAS_ECCENTRICITY_TOLERANCE: Bool = false,
    CO_ORBITAL_TOLERANCE: Double = 0.0,
    CO_ORBITAL_TOLERANCE_BASIS: mplToleranceBasis = .absolutekm,
