    mplPhasingRequest.add(REVOLUTIONS: REVOLUTIONS, &fbb)
    mplPhasingRequest.add(HAS_REVOLUTIONS: HAS_REVOLUTIONS, &fbb)
    mplPhasingRequest.add(MAX_REVOLUTIONS: MAX_REVOLUTIONS, &fbb)
    mplPhasingRequest.add(CHASER: CHASER, &fbb)
    mplPhasingRequest.add(TARGET: TARGET, &fbb)
    mplPhasingRequest.add(DIRECTION: DIRECTION, &fbb)
    mplPhasingRequest.add(DELTA_V_BUDGET_KM_S: DELTA_V_BUDGET_KM_S, &fbb)
    mplPhasingRequest.add(DELTA_V_BUDGET_FRACTION: DELTA_V_BUDGET_FRACTION, &fbb)
