    mplPhasingRequest.add(ECCENTRICITY_TOLERANCE: ECCENTRICITY_TOLERANCE, &fbb)
    mplPhasingRequest.add(HAS_ECCENTRICITY_TOLERANCE: HAS_ECCENTRICITY_TOLERANCE, &fbb)
    mplPhasingRequest.add(CO_ORBITAL_TOLERANCE: CO_ORBITAL_TOLERANCE, &fbb)
    mplPhasingRequest.add(CO_ORBITAL_TOLERANCE_BASIS: CO_ORBITAL_TOLERANCE_BASIS, &fbb)
    mplPhasingRequest.add(HAS_CO_ORBITAL_TOLERANCE: HAS_CO_ORBITAL_TOLERANCE, &fbb)
