    try _v.visit(field: VT.TARGET, fieldName: "TARGET", required: false, type: ForwardOffset<mplOrbit>.self)
    try _v.visit(field: VT.DIRECTION, fieldName: "DIRECTION", required: false, type: mplPhasingDirection.self)
    try _v.visit(field: VT.DELTA_V_BUDGET_KM_S, fieldName: "DELTA_V_BUDGET_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.DELTA_V_BUDGET_FRACTION, fieldName: "DELTA_V_BUDGET_FRACTION", required: false, type: Double.self)
    try _v.visit(field: VT.COPLANAR_TOLERANCE_DEG, fieldName: "COPLANAR_TOLERANCE_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_COPLANAR_TOLERANCE, fieldName: "HAS_COPLANAR_TOLERANCE", required: false, type: Bool.self)
    try _v.visit(field: VT.ECCENTRICITY_TOLERANCE, fieldName: "ECCENTRICITY_TOLERANCE", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_ECCENTRICITY_TOLERANCE, fieldName: "HAS_ECCENTRICITY_TOLERANCE", required: false, type: Bool.self)
    try _v.visit(field: VT.CO_ORBITAL_TOLERANCE, fieldName: "CO_ORBITAL_TOLERANCE", required: false, type: Double.self)
