///  A differential-drag model for relative motion.
public struct mplDifferentialDrag: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MPL" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: mplDifferentialDrag.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let MODEL: VOffset = 4
    static let DA_DOT_PER_S: VOffset = 6
    static let DEX_DOT_PER_S: VOffset = 8
    static let DEY_DOT_PER_S: VOffset = 10
  }

  ///  Which drag model; J2DragEccentric or J2DragArbitrary.
  public var MODEL: mplRelativeDynamics { let o = _accessor.offset(VT.MODEL); return o == 0 ? .j2drageccentric : mplRelativeDynamics(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .j2drageccentric }
  ///  Differential drag rates of the dimensionless relative orbital
  ///  elements, 1/s: of the relative semi-major axis da (multiply by the
  ///  reference semi-major axis for a length rate), and of the relative
  ///  eccentricity-vector components dex and dey. DA_DOT_PER_S alone for
  ///  J2DragEccentric; all three for J2DragArbitrary.
  public var DA_DOT_PER_S: Double { let o = _accessor.offset(VT.DA_DOT_PER_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var DEX_DOT_PER_S: Double { let o = _accessor.offset(VT.DEX_DOT_PER_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var DEY_DOT_PER_S: Double { let o = _accessor.offset(VT.DEY_DOT_PER_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public static func startmplDifferentialDrag(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 4) }
  public static func add(MODEL: mplRelativeDynamics, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MODEL.rawValue, def: 3, at: VT.MODEL) }
  public static func add(DA_DOT_PER_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DA_DOT_PER_S, def: 0.0, at: VT.DA_DOT_PER_S) }
  public static func add(DEX_DOT_PER_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DEX_DOT_PER_S, def: 0.0, at: VT.DEX_DOT_PER_S) }
  public static func add(DEY_DOT_PER_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DEY_DOT_PER_S, def: 0.0, at: VT.DEY_DOT_PER_S) }
  public static func endmplDifferentialDrag(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createmplDifferentialDrag(
    _ fbb: inout FlatBufferBuilder,
    MODEL: mplRelativeDynamics = .j2drageccentric,
    DA_DOT_PER_S: Double = 0.0,
    DEX_DOT_PER_S: Double = 0.0,
    DEY_DOT_PER_S: Double = 0.0
  ) -> Offset {
    let __start = mplDifferentialDrag.startmplDifferentialDrag(&fbb)
    mplDifferentialDrag.add(MODEL: MODEL, &fbb)
    mplDifferentialDrag.add(DA_DOT_PER_S: DA_DOT_PER_S, &fbb)
    mplDifferentialDrag.add(DEX_DOT_PER_S: DEX_DOT_PER_S, &fbb)
    mplDifferentialDrag.add(DEY_DOT_PER_S: DEY_DOT_PER_S, &fbb)
    return mplDifferentialDrag.endmplDifferentialDrag(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.MODEL, fieldName: "MODEL", required: false, type: mplRelativeDynamics.self)
    try _v.visit(field: VT.DA_DOT_PER_S, fieldName: "DA_DOT_PER_S", required: false, type: Double.self)
    try _v.visit(field: VT.DEX_DOT_PER_S, fieldName: "DEX_DOT_PER_S", required: false, type: Double.self)
    try _v.visit(field: VT.DEY_DOT_PER_S, fieldName: "DEY_DOT_PER_S", required: false, type: Double.self)
    _v.finish()
  }
}

