    try _v.visit(field: VT.VELOCITY_KM_S, fieldName: "VELOCITY_KM_S", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.TIME_OF_FLIGHT_S, fieldName: "TIME_OF_FLIGHT_S", required: false, type: Double.self)
    _v.finish()
