  public static func createmplPhasingSolution(
    _ fbb: inout FlatBufferBuilder,
    PHASE_ANGLE_DEG: Double = 0.0,
    ACHIEVED_PHASE_ANGLE_DEG: Double = 0.0,
    REQUESTED_SEMI_MAJOR_AXIS_KM: Double = 0.0,
    REQUESTED_PERIOD_S: Double = 0.0,
    FLOOR_RADIUS_KM: Double = 0.0,
    CLAMPED_TO_FLOOR: Bool = false,
    FAR_APSE_RADIUS_KM: Double = 0.0,
    PHASING_RADIUS_KM: Double = 0.0,
    RELATIVE_PHASE_ANGLE_DEG: Double = 0.0,
    CATCH_UP_ANGLE_DEG: Double = 0.0,
    FALL_BEHIND_ANGLE_DEG: Double = 0.0,
    DIRECTION: mplPhasingDirection = .shortest,
    CHASEROffset CHASER: Offset = Offset(),
    TARGETOffset TARGET: Offset = Offset(),
    RAAN_DIFFERENCE_DEG: Double = 0.0,
    INCLINATION_DIFFERENCE_DEG: Double = 0.0,
    PLANE_ANGLE_DEG: Double = 0.0,
    SEMI_MAJOR_AXIS_DIFFERENCE_KM: Double = 0.0,
    COPLANAR: Bool = false,
    COPLANAR_TOLERANCE_DEG: Double = 0.0,
    NEAR_CIRCULAR: Bool = false,
    ECCENTRICITY_TOLERANCE: Double = 0.0,
    CO_ORBITAL: Bool = false,
    CO_ORBITAL_TOLERANCE_KM: Double = 0.0,
    CO_ORBITAL_TOLERANCE_FRACTION: Double = 0.0,
    RECOMMENDED_REVOLUTIONS: UInt32 = 0,
    REVOLUTIONS_FROM_CALLER: Bool = false,
    MAX_REVOLUTIONS: UInt32 = 0,
    DELTA_V_BUDGET_KM_S: Double = 0.0,
    WITHIN_BUDGET: Bool = false
  ) -> Offset {
    let __start = mplPhasingSolution.startmplPhasingSolution(&fbb)
    mplPhasingSolution.add(PHASE_ANGLE_DEG: PHASE_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(ACHIEVED_PHASE_ANGLE_DEG: ACHIEVED_PHASE_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(REQUESTED_SEMI_MAJOR_AXIS_KM: REQUESTED_SEMI_MAJOR_AXIS_KM, &fbb)
    mplPhasingSolution.add(REQUESTED_PERIOD_S: REQUESTED_PERIOD_S, &fbb)
    mplPhasingSolution.add(FLOOR_RADIUS_KM: FLOOR_RADIUS_KM, &fbb)
    mplPhasingSolution.add(CLAMPED_TO_FLOOR: CLAMPED_TO_FLOOR, &fbb)
    mplPhasingSolution.add(FAR_APSE_RADIUS_KM: FAR_APSE_RADIUS_KM, &fbb)
    mplPhasingSolution.add(PHASING_RADIUS_KM: PHASING_RADIUS_KM, &fbb)
    mplPhasingSolution.add(RELATIVE_PHASE_ANGLE_DEG: RELATIVE_PHASE_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(CATCH_UP_ANGLE_DEG: CATCH_UP_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(FALL_BEHIND_ANGLE_DEG: FALL_BEHIND_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(DIRECTION: DIRECTION, &fbb)
    mplPhasingSolution.add(CHASER: CHASER, &fbb)
    mplPhasingSolution.add(TARGET: TARGET, &fbb)
    mplPhasingSolution.add(RAAN_DIFFERENCE_DEG: RAAN_DIFFERENCE_DEG, &fbb)
    mplPhasingSolution.add(INCLINATION_DIFFERENCE_DEG: INCLINATION_DIFFERENCE_DEG, &fbb)
    mplPhasingSolution.add(PLANE_ANGLE_DEG: PLANE_ANGLE_DEG, &fbb)
    mplPhasingSolution.add(SEMI_MAJOR_AXIS_DIFFERENCE_KM: SEMI_MAJOR_AXIS_DIFFERENCE_KM, &fbb)
    mplPhasingSolution.add(COPLANAR: COPLANAR, &fbb)
    mplPhasingSolution.add(COPLANAR_TOLERANCE_DEG: COPLANAR_TOLERANCE_DEG, &fbb)
    mplPhasingSolution.add(NEAR_CIRCULAR: NEAR_CIRCULAR, &fbb)
    mplPhasingSolution.add(ECCENTRICITY_TOLERANCE: ECCENTRICITY_TOLERANCE, &fbb)
    mplPhasingSolution.add(CO_ORBITAL: CO_ORBITAL, &fbb)
    mplPhasingSolution.add(CO_ORBITAL_TOLERANCE_KM: CO_ORBITAL_TOLERANCE_KM, &fbb)
    mplPhasingSolution.add(CO_ORBITAL_TOLERANCE_FRACTION: CO_ORBITAL_TOLERANCE_FRACTION, &fbb)
    mplPhasingSolution.add(RECOMMENDED_REVOLUTIONS: RECOMMENDED_REVOLUTIONS, &fbb)
    mplPhasingSolution.add(REVOLUTIONS_FROM_CALLER: REVOLUTIONS_FROM_CALLER, &fbb)
    mplPhasingSolution.add(MAX_REVOLUTIONS: MAX_REVOLUTIONS, &fbb)
    mplPhasingSolution.add(DELTA_V_BUDGET_KM_S: DELTA_V_BUDGET_KM_S, &fbb)
    mplPhasingSolution.add(WITHIN_BUDGET: WITHIN_BUDGET, &fbb)
    return mplPhasingSolution.endmplPhasingSolution(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.PHASE_ANGLE_DEG, fieldName: "PHASE_ANGLE_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.ACHIEVED_PHASE_ANGLE_DEG, fieldName: "ACHIEVED_PHASE_ANGLE_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.REQUESTED_SEMI_MAJOR_AXIS_KM, fieldName: "REQUESTED_SEMI_MAJOR_AXIS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.REQUESTED_PERIOD_S, fieldName: "REQUESTED_PERIOD_S", required: false, type: Double.self)
    try _v.visit(field: VT.FLOOR_RADIUS_KM, fieldName: "FLOOR_RADIUS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.CLAMPED_TO_FLOOR, fieldName: "CLAMPED_TO_FLOOR", required: false, type: Bool.self)
    try _v.visit(field: VT.FAR_APSE_RADIUS_KM, fieldName: "FAR_APSE_RADIUS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.PHASING_RADIUS_KM, fieldName: "PHASING_RADIUS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.RELATIVE_PHASE_ANGLE_DEG, fieldName: "RELATIVE_PHASE_ANGLE_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.CATCH_UP_ANGLE_DEG, fieldName: "CATCH_UP_ANGLE_DEG", required: false, type: Double.self)
