  public static func createmplRelativeSolution(
    _ fbb: inout FlatBufferBuilder,
    MODEL_REFERENCEOffset MODEL_REFERENCE: Offset = Offset(),
    DYNAMICS: mplRelativeDynamics = .unspecified,
    STM_DYNAMICS: mplRelativeDynamics = .unspecified,
    STATE_TRANSITIONVectorOffset STATE_TRANSITION: Offset = Offset(),
    DRAG_COLUMNSVectorOffset DRAG_COLUMNS: Offset = Offset(),
    DRAG_COLUMN_COUNT: UInt8 = 0,
    INITIAL_ROEVectorOffset INITIAL_ROE: Offset = Offset(),
    PROPAGATED_ROEVectorOffset PROPAGATED_ROE: Offset = Offset(),
    ACHIEVED_MISS_KM: Double = 0.0,
    FEASIBLE: Bool = false,
    CORRIDOR_DEVIATION_KM: Double = 0.0,
    WITHIN_CORRIDOR: Bool = false
  ) -> Offset {
    let __start = mplRelativeSolution.startmplRelativeSolution(&fbb)
    mplRelativeSolution.add(MODEL_REFERENCE: MODEL_REFERENCE, &fbb)
    mplRelativeSolution.add(DYNAMICS: DYNAMICS, &fbb)
    mplRelativeSolution.add(STM_DYNAMICS: STM_DYNAMICS, &fbb)
    mplRelativeSolution.addVectorOf(STATE_TRANSITION: STATE_TRANSITION, &fbb)
    mplRelativeSolution.addVectorOf(DRAG_COLUMNS: DRAG_COLUMNS, &fbb)
    mplRelativeSolution.add(DRAG_COLUMN_COUNT: DRAG_COLUMN_COUNT, &fbb)
    mplRelativeSolution.addVectorOf(INITIAL_ROE: INITIAL_ROE, &fbb)
    mplRelativeSolution.addVectorOf(PROPAGATED_ROE: PROPAGATED_ROE, &fbb)
    mplRelativeSolution.add(ACHIEVED_MISS_KM: ACHIEVED_MISS_KM, &fbb)
    mplRelativeSolution.add(FEASIBLE: FEASIBLE, &fbb)
    mplRelativeSolution.add(CORRIDOR_DEVIATION_KM: CORRIDOR_DEVIATION_KM, &fbb)
    mplRelativeSolution.add(WITHIN_CORRIDOR: WITHIN_CORRIDOR, &fbb)
    return mplRelativeSolution.endmplRelativeSolution(&fbb, start: __start)
