    try _v.visit(field: VT.STATE_TRANSITION, fieldName: "STATE_TRANSITION", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.DRAG_COLUMNS, fieldName: "DRAG_COLUMNS", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.DRAG_COLUMN_COUNT, fieldName: "DRAG_COLUMN_COUNT", required: false, type: UInt8.self)
    try _v.visit(field: VT.INITIAL_ROE, fieldName: "INITIAL_ROE", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.PROPAGATED_ROE, fieldName: "PROPAGATED_ROE", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.ACHIEVED_MISS_KM, fieldName: "ACHIEVED_MISS_KM", required: false, type: Double.self)
    try _v.visit(field: VT.FEASIBLE, fieldName: "FEASIBLE", required: false, type: Bool.self)
    try _v.visit(field: VT.CORRIDOR_DEVIATION_KM, fieldName: "CORRIDOR_DEVIATION_KM", required: false, type: Double.self)
    try _v.visit(field: VT.WITHIN_CORRIDOR, fieldName: "WITHIN_CORRIDOR", required: false, type: Bool.self)
    _v.finish()
  }
