  public static func createMPL(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset = Offset(),
    CREATED_AT_MS: Int64 = 0,
    PLANNEROffset PLANNER: Offset = Offset(),
    PROBLEM: mplProblem = .unspecified,
    PLAN_EPOCH_MS: Int64 = 0,
    OBJECT_IDOffset OBJECT_ID: Offset = Offset(),
    TARGET_OBJECT_IDOffset TARGET_OBJECT_ID: Offset = Offset(),
    REFERENCE_FRAMEOffset REFERENCE_FRAME: Offset = Offset(),
    REQUESTOffset REQUEST: Offset = Offset(),
    STATUS: mplStatus = .pending,
    ERROR_CODEOffset ERROR_CODE: Offset = Offset(),
    ERROR_MESSAGEOffset ERROR_MESSAGE: Offset = Offset(),
    BURNSVectorOffset BURNS: Offset = Offset(),
    ARCSVectorOffset ARCS: Offset = Offset(),
    TOTAL_DELTA_V_KM_S: Double = 0.0,
    TOTAL_TIME_S: Double = 0.0,
    TOTAL_DELTA_MASS_KG: Double = 0.0,
    SOLVEROffset SOLVER: Offset = Offset(),
    OPTIONSVectorOffset OPTIONS: Offset = Offset(),
    TRAJECTORYOffset TRAJECTORY: Offset = Offset(),
    PHASINGOffset PHASING: Offset = Offset(),
    RELATIVEOffset RELATIVE: Offset = Offset(),
    RENDEZVOUSOffset RENDEZVOUS: Offset = Offset(),
    GEOMETRYOffset GEOMETRY: Offset = Offset()
  ) -> Offset {
    let __start = MPL.startMPL(&fbb)
    MPL.add(ID: ID, &fbb)
    MPL.add(CREATED_AT_MS: CREATED_AT_MS, &fbb)
    MPL.add(PLANNER: PLANNER, &fbb)
    MPL.add(PROBLEM: PROBLEM, &fbb)
    MPL.add(PLAN_EPOCH_MS: PLAN_EPOCH_MS, &fbb)
    MPL.add(OBJECT_ID: OBJECT_ID, &fbb)
    MPL.add(TARGET_OBJECT_ID: TARGET_OBJECT_ID, &fbb)
    MPL.add(REFERENCE_FRAME: REFERENCE_FRAME, &fbb)
    MPL.add(REQUEST: REQUEST, &fbb)
    MPL.add(STATUS: STATUS, &fbb)
    MPL.add(ERROR_CODE: ERROR_CODE, &fbb)
    MPL.add(ERROR_MESSAGE: ERROR_MESSAGE, &fbb)
    MPL.addVectorOf(BURNS: BURNS, &fbb)
    MPL.addVectorOf(ARCS: ARCS, &fbb)
    MPL.add(TOTAL_DELTA_V_KM_S: TOTAL_DELTA_V_KM_S, &fbb)
    MPL.add(TOTAL_TIME_S: TOTAL_TIME_S, &fbb)
    MPL.add(TOTAL_DELTA_MASS_KG: TOTAL_DELTA_MASS_KG, &fbb)
    MPL.add(SOLVER: SOLVER, &fbb)
    MPL.addVectorOf(OPTIONS: OPTIONS, &fbb)
    MPL.add(TRAJECTORY: TRAJECTORY, &fbb)
    MPL.add(PHASING: PHASING, &fbb)
    MPL.add(RELATIVE: RELATIVE, &fbb)
    MPL.add(RENDEZVOUS: RENDEZVOUS, &fbb)
    MPL.add(GEOMETRY: GEOMETRY, &fbb)
    return MPL.endMPL(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ID, fieldName: "ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CREATED_AT_MS, fieldName: "CREATED_AT_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PLANNER, fieldName: "PLANNER", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROBLEM, fieldName: "PROBLEM", required: false, type: mplProblem.self)
    try _v.visit(field: VT.PLAN_EPOCH_MS, fieldName: "PLAN_EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.OBJECT_ID, fieldName: "OBJECT_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TARGET_OBJECT_ID, fieldName: "TARGET_OBJECT_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.REFERENCE_FRAME, fieldName: "REFERENCE_FRAME", required: false, type: ForwardOffset<RFM>.self)
    try _v.visit(field: VT.REQUEST, fieldName: "REQUEST", required: false, type: ForwardOffset<mplRequest>.self)
    try _v.visit(field: VT.STATUS, fieldName: "STATUS", required: false, type: mplStatus.self)
    try _v.visit(field: VT.ERROR_CODE, fieldName: "ERROR_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ERROR_MESSAGE, fieldName: "ERROR_MESSAGE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BURNS, fieldName: "BURNS", required: false, type: ForwardOffset<Vector<ForwardOffset<mplBurn>, mplBurn>>.self)
    try _v.visit(field: VT.ARCS, fieldName: "ARCS", required: false, type: ForwardOffset<Vector<ForwardOffset<mplArc>, mplArc>>.self)
    try _v.visit(field: VT.TOTAL_DELTA_V_KM_S, fieldName: "TOTAL_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.TOTAL_TIME_S, fieldName: "TOTAL_TIME_S", required: false, type: Double.self)
    try _v.visit(field: VT.TOTAL_DELTA_MASS_KG, fieldName: "TOTAL_DELTA_MASS_KG", required: false, type: Double.self)
    try _v.visit(field: VT.SOLVER, fieldName: "SOLVER", required: false, type: ForwardOffset<mplSolver>.self)
    try _v.visit(field: VT.OPTIONS, fieldName: "OPTIONS", required: false, type: ForwardOffset<Vector<ForwardOffset<mplOption>, mplOption>>.self)
    try _v.visit(field: VT.TRAJECTORY, fieldName: "TRAJECTORY", required: false, type: ForwardOffset<mplTrajectory>.self)
    try _v.visit(field: VT.PHASING, fieldName: "PHASING", required: false, type: ForwardOffset<mplPhasingSolution>.self)
    try _v.visit(field: VT.RELATIVE, fieldName: "RELATIVE", required: false, type: ForwardOffset<mplRelativeSolution>.self)
    try _v.visit(field: VT.RENDEZVOUS, fieldName: "RENDEZVOUS", required: false, type: ForwardOffset<mplRendezvousSolution>.self)
    try _v.visit(field: VT.GEOMETRY, fieldName: "GEOMETRY", required: false, type: ForwardOffset<mplGeometrySolution>.self)
    _v.finish()
  }
